-- Staged migration for personal-trainer-mvp. implement-tasks promotes it (re-stamped) into an EF Core migration via migrationBuilder.Sql.
-- Відновлює структуру групової моделі (без даних — дані відновлюються з pg_dump).
CREATE TABLE IF NOT EXISTS "Words" (
    "Id"                     INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "TargetWord"             VARCHAR(200) NOT NULL,
    "SourceMeaning"          VARCHAR(500) NOT NULL,
    "PhoneticTranscription"  VARCHAR(200) NOT NULL,
    "FrequencyRank"          INTEGER      NOT NULL,
    "ImportedAt"             TIMESTAMPTZ  NOT NULL
);
CREATE INDEX IF NOT EXISTS "IX_Words_FrequencyRank" ON "Words" ("FrequencyRank");
CREATE TABLE IF NOT EXISTS "ChatRegistrations" (
    "Id"                    INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ChatId"                BIGINT       NOT NULL,
    "ChatTitle"             VARCHAR(200) NULL,
    "RegisteredAt"          TIMESTAMPTZ  NOT NULL,
    "IsActive"              BOOLEAN      NOT NULL,
    "RepetitionTime"        VARCHAR(5)   NOT NULL,
    "NewWordsTime"          VARCHAR(5)   NOT NULL,
    "NewWordsCount"         INTEGER      NOT NULL,
    "RepetitionWordsCount"  INTEGER      NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_ChatRegistrations_ChatId" ON "ChatRegistrations" ("ChatId");
CREATE TABLE IF NOT EXISTS "LearnedWords" (
    "Id"               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ChatId"           BIGINT      NOT NULL,
    "WordId"           INTEGER     NOT NULL REFERENCES "Words" ("Id") ON DELETE CASCADE,
    "LearnedAt"        TIMESTAMPTZ NOT NULL,
    "LastRepeatedAt"   TIMESTAMPTZ NOT NULL,
    "RepetitionCount"  INTEGER     NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_LearnedWords_ChatId_WordId" ON "LearnedWords" ("ChatId", "WordId");
CREATE INDEX IF NOT EXISTS "IX_LearnedWords_WordId" ON "LearnedWords" ("WordId");
